package controlsys

import (
	"math"
	"testing"

	"plantcontrol.org/v1/gonum/mat"
)

// NDFJC6: the least-squares integrator count takes a pole only when
// rounding of the realization can carry it to s = 0 (originUnresolvedPoles)
// and its limit lim s^k G(s) exceeds the limit's own rounding bound
// (integratorStaircase); otherwise the fit holds a pole exactly at z = 1
// that the stored model does not have.

// The 41-state n41_uncontrollable_pole_at_zero source of
// TestLeastSquaresHighOrderSources as the NGG5TW Reduce keeps it (arm64):
// a rotated uncontrollable pole stored at λ ≈ 4.9e-16, whose limit
// −1.6e-16 is rounding. Its exact 1/s coefficient is 0.
func TestIntegratorStaircaseLimitDropsRoundingLevelResidue(t *testing.T) {
	sys := integratorRoundingResidueN41(t)
	k, limit, bound, err := integratorStaircase(sys, true, 0.1, 41)
	if err != nil || k != 1 || !(math.Abs(limit) <= bound) {
		t.Fatalf("one staircase step: k=%d limit %g bound %g err %v, want k=1 with |limit| ≤ bound", k, limit, bound, err)
	}
	if k, limit, err := integratorStaircaseLimit(sys, true, 0.1); err != nil || k != 0 || limit != 0 {
		t.Fatalf("integrators %d limit %g err %v, want 0", k, limit, err)
	}
}

// nse-rot 355 and 1342 of the NGG5TW downstream spot census (arm64), the
// explicit fold of a near-singular descriptor whose slow poles NGG5TW's
// Reduce keeps: their computed poles are within rounding of s = 0 on the
// scale of the stiff pole (355 has one computed exactly 0, 1342 a pair),
// but their limits are below their rounding bounds, which grow with ‖A‖ as
// the slow residue does not. Main's count held one (355) or two (1342)
// poles at z = 1 with the fit error 3× to 140× that of the free fit.
func TestIntegratorStaircaseLimitDropsStiffSlowPoles(t *testing.T) {
	for _, tc := range []struct {
		name  string
		sys   *System
		steps int
	}{
		{"nse-rot 355", integratorRoundingNSERot355(t), 1},
		{"nse-rot 1342", integratorRoundingNSERot1342(t), 2},
	} {
		n, _, _ := tc.sys.Dims()
		if count, ok := originUnresolvedPoles(tc.sys.A, n, 0.1); !ok || count != tc.steps {
			t.Fatalf("%s: %d poles within rounding of s = 0 (ok %v), want %d", tc.name, count, ok, tc.steps)
		}
		k, limit, bound, err := integratorStaircase(tc.sys, true, 0.1, n)
		if err != nil || k != tc.steps || !(math.Abs(limit) <= bound) {
			t.Fatalf("%s: k=%d limit %g bound %g err %v, want k=%d with |limit| ≤ bound", tc.name, k, limit, bound, err, tc.steps)
		}
		if k, limit, err := integratorStaircaseLimit(tc.sys, true, 0.1); err != nil || k != 0 {
			t.Fatalf("%s: integrators %d limit %g err %v, want 0", tc.name, k, limit, err)
		}
	}
}

// A 3-state rotation of triu(−0.2…−2.2 slow, −6.7e11 fast) (rotfast seed
// 21, arm64): rounding of A moves its slow poles by about 1e-4, so main's
// test (moved by more than 1e-6 of |λ|) took both for integrators, and their
// limit 0.08 is well above its bound. They are located away from s = 0.
func TestLeastSquaresIntegratorLimitSkipsSlowPolesResolvedFromZero(t *testing.T) {
	sys := integratorRoundingRotFast21(t)
	if count, ok := originUnresolvedPoles(sys.A, 3, 0.1); !ok || count != 0 {
		t.Fatalf("%d poles within rounding of s = 0 (ok %v), want 0", count, ok)
	}
	if k, limit, err := leastSquaresIntegratorLimit(sys, true, 0.1); err != nil || k != 0 {
		t.Fatalf("integrators %d limit %g err %v, want 0", k, limit, err)
	}
	d, fit, err := sys.C2DFit(0.1, C2DOptions{Method: C2DMethodLeastSquares})
	if err != nil {
		t.Fatal(err)
	}
	poles, err := d.Poles()
	if err != nil {
		t.Fatal(err)
	}
	for _, p := range poles {
		if p == 1 {
			t.Fatalf("fit holds a pole at z = 1: %v", poles)
		}
	}
	if fit.MaxRelativeError > 1e-2 {
		t.Fatalf("MaxRelativeError %g", fit.MaxRelativeError)
	}
}

